CREATE TABLE IF NOT EXISTS attendance_setting (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, updated_by CHAR(36) NULL, updated_at DATETIME NOT NULL, CONSTRAINT attendance_setting_updated_by_fk FOREIGN KEY (updated_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_shift_type (id CHAR(36) PRIMARY KEY, name VARCHAR(60) NOT NULL, start_minute SMALLINT NOT NULL, end_minute SMALLINT NOT NULL, early_window_minutes SMALLINT NOT NULL, late_grace_minutes SMALLINT NOT NULL, early_leave_grace_minutes SMALLINT NOT NULL, checkout_window_minutes SMALLINT NOT NULL, color_hex CHAR(7) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order SMALLINT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY attendance_shift_type_name_unique (name), CONSTRAINT attendance_shift_type_minutes_check CHECK (start_minute BETWEEN 0 AND 1439 AND end_minute BETWEEN 0 AND 1439 AND start_minute <> end_minute)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_location (id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, latitude DECIMAL(9,6) NOT NULL, longitude DECIMAL(9,6) NOT NULL, radius_meters SMALLINT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY attendance_location_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_device (id CHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, location_id CHAR(36) NOT NULL, public_key_jwk VARCHAR(512) NULL, paired_at DATETIME NULL, revoked_at DATETIME NULL, revoked_by CHAR(36) NULL, last_seen_at DATETIME NULL, created_by CHAR(36) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY attendance_device_location_index (location_id), CONSTRAINT attendance_device_location_fk FOREIGN KEY (location_id) REFERENCES attendance_location(id), CONSTRAINT attendance_device_created_by_fk FOREIGN KEY (created_by) REFERENCES person(id), CONSTRAINT attendance_device_revoked_by_fk FOREIGN KEY (revoked_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_device_pairing (id CHAR(36) PRIMARY KEY, device_id CHAR(36) NOT NULL, code_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL, UNIQUE KEY attendance_device_pairing_code_unique (code_hash), KEY attendance_device_pairing_device_index (device_id), CONSTRAINT attendance_device_pairing_device_fk FOREIGN KEY (device_id) REFERENCES attendance_device(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_request_nonce (device_id CHAR(36) NOT NULL, nonce VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (device_id, nonce), KEY attendance_request_nonce_created_index (created_at), CONSTRAINT attendance_request_nonce_device_fk FOREIGN KEY (device_id) REFERENCES attendance_device(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_hash_chain (seq BIGINT PRIMARY KEY, record_type VARCHAR(32) NOT NULL, record_id CHAR(36) NOT NULL, prev_hash CHAR(64) NOT NULL, hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY attendance_hash_chain_record_unique (record_type, record_id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attendance_hash_chain_head (id TINYINT PRIMARY KEY, last_seq BIGINT NOT NULL, last_hash CHAR(64) NOT NULL) DEFAULT CHARSET=utf8mb4;
